<?php require_once 'functions.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){ $n=trim($_POST['name']??'');$em=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$m=trim($_POST['message']??'');if($n&&$em&&$m){db()->prepare('INSERT INTO support_messages(name,email,message) VALUES(?,?,?)')->execute([$n,$em,$m]);flash('Message saved. The project stores support messages locally; external Getform delivery is not enabled.');redirect('support.php');}flash('Please fill all fields correctly.','error');}$pageTitle='Support';require 'partials/header.php'; ?><div class="support-page"><div class="support-container panel"><h1 class="support-title">Support &amp; Feedback</h1><form method="post" class="support-form"><input type="text" name="name" placeholder="Your Name" required><input type="email" name="email" placeholder="Your Email" required><textarea name="message" rows="5" placeholder="Your Message" required></textarea><button type="submit">Send Message</button></form></div></div><?php require 'partials/footer.php'; ?>